// === Tab: mySketch ===
let drops = [];

function setup() {
  createCanvas(1000, 1000);
  noStroke();
  for (let i = 0; i < 60; i++) {
    drops.push(new OrganicDrop(random(width), random(height), random(15, 35)));
  }
  noCursor();
}

function draw() {
  background(20, 20, 30);

  for (let drop of drops) {
    drop.update();
    drop.show();
  }
}

class OrganicDrop {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.baseSize = size;
    this.size = size;
    this.offset = random(1000);
    this.alpha = random(100, 180);
    this.speed = random(0.5, 1.5);
  }

  update() {
    this.y += this.speed;
    if (this.y > height + this.baseSize) {
      this.y = random(-100, -10);
      this.x = random(width);
    }

    // deformación tipo orgánica
    this.size = this.baseSize + sin(frameCount * 0.1 + this.offset) * 3;
  }

  show() {
    push();
    translate(this.x, this.y);
    fill(180, 220, 255, this.alpha);

    // Forma irregular usando curva orgánica con ruido
    beginShape();
    let totalPoints = 20;
    for (let a = 0; a < TWO_PI; a += TWO_PI / totalPoints) {
      let r = this.size + noise(cos(a) * 0.5 + this.offset, sin(a) * 0.5 + this.offset) * 10;
      let x = cos(a) * r;
      let y = sin(a) * r;
      curveVertex(x, y);
    }
    endShape(CLOSE);

    // Simula reflejo interno
    fill(255, 255, 255, this.alpha + 20);
    ellipse(-this.size * 0.2, -this.size * 0.3, this.size * 0.4, this.size * 0.2);

    pop();
  }
}

// === Tab: shader ===
// Minimal vertex shader
const vert = `
precision highp float;
attribute vec3 aPosition;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
void main() {
  gl_Position = uProjectionMatrix  * uModelViewMatrix * vec4(aPosition, 1.0);  
}
`;

const frag = `
precision highp float;

uniform vec2 uResolution; // screen size
uniform vec2 uPhase; // shifts noise space
uniform float uScale; // scales noise space
uniform int uOctaves; // how many noise octaves
uniform float uFreq; // Pattern frequency
uniform float uNoiseFactor; // How much noise affects the pattern
uniform float uSharpness; // Power factor applied to resulting color
uniform float uTime; // Time in seconds
uniform int uPattern; // Pattern id


// Gradient Noise by Inigo Quilez - iq/2013
// https://www.shadertoy.com/view/Xsl3Dl


vec3 hash( vec3 p ) // replace this by something better
{
	p = vec3( dot(p,vec3(127.1,311.7, 74.7)),
			  dot(p,vec3(269.5,183.3,246.1)),
			  dot(p,vec3(113.5,271.9,124.6)));
	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

float noise3( in vec3 p ) 
{
    vec3 i = floor( p );
    vec3 f = fract( p );
    vec3 u = f*f*(3.0-2.0*f);

    return mix( mix( mix( dot( hash( i + vec3(0.0,0.0,0.0) ), f - vec3(0.0,0.0,0.0) ), 
                          dot( hash( i + vec3(1.0,0.0,0.0) ), f - vec3(1.0,0.0,0.0) ), u.x),
                     mix( dot( hash( i + vec3(0.0,1.0,0.0) ), f - vec3(0.0,1.0,0.0) ), 
                          dot( hash( i + vec3(1.0,1.0,0.0) ), f - vec3(1.0,1.0,0.0) ), u.x), u.y),
                mix( mix( dot( hash( i + vec3(0.0,0.0,1.0) ), f - vec3(0.0,0.0,1.0) ), 
                          dot( hash( i + vec3(1.0,0.0,1.0) ), f - vec3(1.0,0.0,1.0) ), u.x),
                     mix( dot( hash( i + vec3(0.0,1.0,1.0) ), f - vec3(0.0,1.0,1.0) ), 
                          dot( hash( i + vec3(1.0,1.0,1.0) ), f - vec3(1.0,1.0,1.0) ), u.x), u.y), u.z );
}


float octaveNoise (vec3 st, int octaves) {
	float total = 1.;
	float sum = noise3(st);
	if (octaves > 1) {sum += 0.5 * noise3(st*2.); total = 1.8; }
	if (octaves > 2) {sum += 0.25 * noise3(st*4.); total = 1.75; }
	if (octaves > 3) {sum += 0.125 * noise3(st*8.); total = 1.875; }
	if (octaves > 4) {sum += 0.0625 * noise3(st*16.); total = 1.9375; }
	if (octaves > 5) {sum += 0.078125 * noise3(st*32.); total = 1.9; }
	return sum / total;
}

float qsmoothstep (float x) { // quintic smoothstep
  return x*x*x*(x*(x*6.0-15.0)+10.0);
}

void main() {
  vec2 p =  (gl_FragCoord.xy * 2.0 - uResolution) / uResolution.y;
	p = p*uScale+uPhase;
	float displacement = octaveNoise(vec3(p,uTime),uOctaves)*uNoiseFactor;
	float pat = uFreq*length(p - 0.5 * floor (p /0.5 + 0.5));
	if(uPattern==1) {
		vec2 q = p - 0.5 * floor (p /0.5 + 0.5);
		pat = uFreq * (abs(q.x) - abs(q.y));
	}
	if(uPattern==2) pat = sin(uFreq*p.x) * sin(uFreq*p.y);
	if(uPattern==3) {
		float t = cos(uFreq*p.x) * cos(uFreq*p.y);
  	pat = smoothstep(0.1, 0., t*t);
	}
	float gray = cos((pat+displacement)*3.1416)*0.5+0.5;
	vec3 color = vec3(pow(gray,uSharpness));//vec3( sin(uFreq*(pat+displacement))*.5+.5 );
	gl_FragColor = vec4(color,1.);
}
